Definition mballoc_W2 (lo : Z) (sp : word) (A n ff fp : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (A, A + mb_block_size n); (ff, ff + 64); (sh ff, sh ff + 8); (fp, fp + 1)]%Z.

Definition mballoc_seg2_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LF : list fframe) (A n lo shi ff fp : Z) (junkB : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' junk,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch (mballoc_W2 lo sp A n ff fp) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' A [CB 16 (firstn 16 junkB)]
    /\ rw_cells bsegs m' (A + 16) [C8 (Z_to_bv 64 n); CB (Z.to_nat (mb_block_size n - 24)) junk]
    /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.
