Lemma mballoc_seg2 : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (pcv rax t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word)
    (A n spa lo shi ff fp : Z) (LF : list fframe) (m : mem) (pad : list cell) (j24 hjunk sh8 junkB : list byte),
  (pcv = Z_to_bv 64 P_A_MB_ALLOC_NEWRET \/ pcv = ret_pc (Z_to_bv 64 P_A_MB_ALLOC_NEWRET)) ->
  rw_cells bsegs m spa (C8 (Z_to_bv 64 ff) :: pad) -> 8 + Z.of_nat (cells_size pad) = bv_unsigned sp + -88 - spa -> lo <= spa ->
  rw_cells bsegs m (bv_unsigned sp + -88) (mballoc_frame s6 s5 s4 s3 s2 s1 s0 ra j24) ->
  rw_cells bsegs m ff [CB 56 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells bsegs m (Z.shiftr ff 3 + 2147450880) [CB 8 sh8] ->
  rw_cells bsegs m fp [C1 (b8 1)] ->
  rw_cells bsegs m A [CB (Z.to_nat (mb_block_size n)) junkB] -> addressable m A (mb_block_size n) -> rblock_range A (mb_block_size n) ->
  (A + mb_block_size n <= as_FSB H \/ as_FSB H + AFS_SIZE <= A) ->
  stk bsegs m lo spa -> mem_inv bsegs m ->
  as_RFS H ((0, ff, fp) :: LF) m -> fresh_frame H LF 0 ff fp -> ACONST m -> stack0 m lo shi ->
  1 <= n -> n <= 2^28 - 32 ->
  lo + 112 <= bv_unsigned sp -> aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
  evt bsegs (mballoc_seg2_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LF A n lo shi ff fp junkB m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) (Z_to_bv 64 A) a1' a2' a3' a4' a5' a6' a7'
             (Z_to_bv 64 ff) (Z_to_bv 64 n) (Z_to_bv 64 2147450880) (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) s7
             s8 s9 s10 s11 t3' t4' t5' t6')
        F pcv fc None m (seg_rom bsegs)).
